(function () {
  if (!window.FontFace || !document.fonts) return;
  var faces = [["DIN 2014 Bold",""],["DIN 2014 Light",""]];
  window.BRAIN_FONTS = Promise.all(faces.map(function (f) { var face = new FontFace(f[0], 'url(data:font/ttf;base64,' + f[1] + ')'); document.fonts.add(face); return face.load(); }));
})();
